type StatePanelKind = "loading" | "empty" | "error" | "offline" | "forbidden" | "saving" | "not_found" | "partial" | "insufficient_evidence" | "decision_submitted" | "view_drilldown" | "view_trace" | "sync_conflict";

type Tone = "neutral" | "info" | "warn" | "danger";
const stateCopy: Record<StatePanelKind, { title: string; body: string; action: string; label: string; tone: Tone; live: "status" | "alert" }> = {
  loading: { title: "Loading workspace data", body: "Skeleton rows reserve final dimensions while the browser waits on the Go REST API.", action: "EVENT_REFRESH", label: "Refresh from API", tone: "neutral", live: "status" },
  empty: { title: "No records returned", body: "Create or link a plan, task, document, or trace record through the API-backed workspace flow.", action: "EVENT_OPEN_CREATE_PLAN", label: "Create plan", tone: "info", live: "status" },
  error: { title: "API request failed", body: "Repository, database, shell, git, and CI calls remain behind the Go REST boundary. Retry the safe endpoint.", action: "EVENT_REFRESH", label: "Retry request", tone: "danger", live: "alert" },
  offline: { title: "Offline read-only mode", body: "Cached details remain visible. Edits wait until the API reconnects and confirms the server version.", action: "EVENT_RECONNECT", label: "Reconnect", tone: "warn", live: "status" },
  forbidden: { title: "Permission required", body: "This route needs a PM, RTE, or approver capability. Ask an administrator to update role grants server-side.", action: "EVENT_BACK", label: "Go back", tone: "danger", live: "alert" },
  saving: { title: "Saving draft through API", body: "Changes are staged for PUT through the Go REST endpoint; no browser-side file or database access occurs.", action: "EVENT_FIELD_EDIT", label: "Review draft", tone: "info", live: "status" },
  not_found: { title: "Requested record was not found", body: "The task, storyboard, or trace ID may have moved. Return to the API list and choose an available result.", action: "EVENT_BACK", label: "Back to list", tone: "warn", live: "alert" },
  partial: { title: "Partial trace loaded", body: "The graph reached a depth cap or stale node. Continue with visible evidence or request focused trace refresh.", action: "EVENT_VIEW_TRACE", label: "Refresh trace", tone: "warn", live: "status" },
  insufficient_evidence: { title: "Approval evidence incomplete", body: "Attach test results, PRD trace, and decision notes before approving or rejecting through the approval endpoint.", action: "EVENT_APPROVAL_DECISION", label: "Review evidence", tone: "warn", live: "alert" },
  decision_submitted: { title: "Decision submitted", body: "The approval decision is queued as an auditable REST mutation with PM notes and beads trace links.", action: "EVENT_VIEW_TRACE", label: "View audit trace", tone: "info", live: "status" },
  view_drilldown: { title: "Drill-down opened", body: "Dashboard focus moved to the gap and task evidence behind the selected coverage panel.", action: "EVENT_VIEW_TASK", label: "Open task evidence", tone: "info", live: "status" },
  view_trace: { title: "Trace view opened", body: "The dashboard is showing the PRD-to-task-to-CI trace path requested from the storyboard action.", action: "EVENT_VIEW_TRACE", label: "Open trace explorer", tone: "info", live: "status" },
  sync_conflict: { title: "Server version changed", body: "Review the newer API version before resubmitting local edits, then keep mine or use the server version.", action: "EVENT_KEEP_MINE_OR_USE_SERVER", label: "Resolve conflict", tone: "warn", live: "alert" },
};
const toneClass: Record<Tone, string> = { neutral: "border-[var(--border)]", info: "border-[var(--accent-cyan-dim)]", warn: "border-[var(--accent-amber-dim)]", danger: "border-[var(--accent-rose-dim)]" };

type IconName = "status" | "loading" | "empty" | "error" | "offline" | "forbidden" | "saving" | "partial" | "approve" | "reject" | "changes" | "trace" | "docs" | "task" | "search" | "move" | "filter" | "api" | "download" | "list" | "board";
const iconPaths: Record<IconName, ReactNode> = {
  status: <><circle cx="12" cy="12" r="8" /><path d="m8.5 12 2.5 2.5L16 9" /></>, loading: <><path d="M12 4v4M12 16v4M4 12h4M16 12h4" /><path d="m6.3 6.3 2.8 2.8M14.9 14.9l2.8 2.8" /></>, empty: <><path d="M5 6h14v12H5z" /><path d="M9 10h6" /></>, error: <><path d="M12 4 3 20h18z" /><path d="M12 9v4M12 17h.01" /></>, offline: <><circle cx="12" cy="12" r="8" /><path d="M8 8l8 8M16 8l-8 8" /></>, forbidden: <><circle cx="12" cy="12" r="8" /><path d="M8 16 16 8" /></>, saving: <><path d="M5 4h11l3 3v13H5z" /><path d="M8 4v6h8M8 17h8" /></>, partial: <><path d="M4 12h16" /><path d="M4 12a8 8 0 0 1 8-8" /><path d="M12 20a8 8 0 0 0 8-8" /></>, approve: <path d="m4 12 5 5L20 6" />, reject: <path d="M6 6l12 12M18 6 6 18" />, changes: <><path d="M4 7h10M4 12h16M4 17h10" /><path d="m16 5 3 2-3 2M16 15l3 2-3 2" /></>, trace: <><circle cx="5" cy="12" r="2" /><circle cx="12" cy="6" r="2" /><circle cx="19" cy="12" r="2" /><path d="m7 11 3.5-3M13.5 7 17 11" /></>, docs: <><path d="M6 3h9l3 3v15H6z" /><path d="M9 12h6M9 16h6" /></>, task: <><path d="M8 7h12M8 12h12M8 17h12" /><path d="m3.5 12 1 1 2-2" /></>, search: <><circle cx="11" cy="11" r="6" /><path d="m16 16 4 4" /></>, move: <><path d="M5 12h14" /><path d="m15 8 4 4-4 4" /></>, filter: <><path d="M4 6h16M7 12h10M10 18h4" /></>, api: <><path d="M7 7h10v10H7z" /><path d="M3 10h4M3 14h4M17 10h4M17 14h4" /></>, download: <><path d="M12 4v10" /><path d="m8 10 4 4 4-4" /><path d="M5 20h14" /></>, list: <><path d="M8 6h12M8 12h12M8 18h12" /><path d="M4 6h.01M4 12h.01M4 18h.01" /></>, board: <><path d="M4 5h16" /><path d="M8 5v15M16 5v15" /><path d="M5 9h2M13 13h2M17 9h2" /></>,
};
function Icon({ name, className = "h-4 w-4" }: { name: IconName; className?: string }) { return <svg aria-hidden="true" viewBox="0 0 24 24" className={`${className} shrink-0`} fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">{iconPaths[name]}</svg>; }
function iconForState(state: StatePanelKind): IconName { if (state === "loading") return "loading"; if (state === "empty") return "empty"; if (state === "error") return "error"; if (state === "offline") return "offline"; if (state === "forbidden") return "forbidden"; if (state === "saving") return "saving"; if (state === "partial") return "partial"; return "status"; }

