export function WorkspaceStatePanel({ state, compact = false }: { state: StatePanelKind; compact?: boolean }) {
  const copy = stateCopy[state];
  const liveProps = copy.live === "alert" ? { role: "alert" } : { role: "status", "aria-live": "polite" as const };
  return <aside data-state={state} aria-label={`${copy.title} state recovery`} className={`rounded-[var(--radius)] border ${toneClass[copy.tone]} bg-[var(--bg)] p-[var(--space-sm)]`} {...liveProps}>{state === "loading" ? <SkeletonRows /> : null}<p className="inline-flex items-center gap-[var(--space-xs)] font-mono text-xs uppercase tracking-[0.14em] text-[var(--text-dim)]"><Icon name={iconForState(state)} />{state.replaceAll("_", " ")}</p><h3 className="mt-[var(--space-xs)] font-semibold">{copy.title}</h3><p className={`mt-[var(--space-xs)] text-sm ${muted}`}>{copy.body}</p><a href={`#${copy.action.toLowerCase().replaceAll("_", "-")}`} data-action={copy.action} className={`mt-[var(--space-sm)] inline-flex ${compact ? "btn-sm" : ""} btn-secondary ${focus}`}><Icon name={iconForState(state)} />{copy.label}</a></aside>;
}
function SkeletonRows() { return <div className="skeleton-group" aria-hidden="true"><div className="skeleton skeleton--text-full" /><div className="skeleton skeleton--text-short" /><div className="skeleton skeleton--card" /></div>; }
// Layout Decision: Shell acts as the content wrapper inside the outer card (article wrapper in WebUIPMWorkspacePage.tsx).
// Refactored from <article className="border bg-[var(--surface)] p-[var(--space-sm)]"> to a simple <div>
// to eliminate redundant double nesting borders, backgrounds, and stacked padding variables that break card layouts.
function Shell({ dsId, children, state = "default", label }: { dsId: string; children: ReactNode; state?: string; label?: string }) { return <div data-ds-id={dsId} data-state={state} aria-label={label} className="min-w-0 w-full h-full flex flex-col justify-between gap-[var(--space-sm)]">{children}</div>; }
function ApiLabel({ children }: { children: ReactNode }) { return <code className="rounded-[var(--radius)] bg-[var(--bg)] px-[var(--space-xs)] py-[2px] font-mono text-[0.68rem] text-[var(--text-dim)]">{children}</code>; }
function Status({ value }: { value: string }) { return <span className={`badge inline-flex items-center gap-[var(--space-xs)] ${value === "Blocked" || value === "High" ? "badge-rose" : value === "In Review" || value === "Medium" ? "badge-amber" : "badge-teal"}`}><Icon name={value === "Blocked" || value === "High" ? "error" : value === "In Review" || value === "Medium" ? "partial" : "status"} className="h-3 w-3" />{value}</span>; }

