function DagLayers() { return <Shell dsId="ds:webui.trace.legend-stats"><ol className="grid gap-[var(--space-xs)] sm:grid-cols-5">{["prd-sections","plan-elements","tasks","commits","ci"].map(layer => <li key={layer} className="rounded-[var(--radius)] bg-[var(--bg)] p-[var(--space-xs)] text-sm">{layer}</li>)}</ol></Shell>; }
function NodeDetail() { return <Shell dsId="ds:webui.trace.detail-panel"><h3 className="font-semibold">Selected node</h3><dl className="mt-[var(--space-sm)] grid gap-[var(--space-xs)] text-sm"><dt className="font-mono text-xs text-[var(--text-dim)]">Beads ID</dt><dd>br-prd04-s5</dd><dt className="font-mono text-xs text-[var(--text-dim)]">Impact</dt><dd>Approval gate, task detail, QA evidence, Go API adapter.</dd></dl></Shell>; }
