function MarkdownViewer() { return <Shell dsId="ds:webui.docs.content"><h3 className="font-semibold">PRD-04 excerpt</h3><p className="mt-[var(--space-sm)] text-sm">The PM Workspace supervises the Pyramid of Knowledge through Go REST endpoints. Browser actions navigate to documents and trace IDs; repository, database, shell, and CI operations remain server-side.</p><a href="#surface-trace" data-action="EVENT_VIEW_TRACE" data-action-id="action-rtm-open-trace" data-event="EVENT_RTM_OPEN_TRACE" className={`mt-[var(--space-sm)] inline-flex badge badge-cyan ${focus}`}>br-prd04-s5</a></Shell>; }
function SectionBadges() { return <Shell dsId="ds:webui.docs.section-badges"><div className="flex flex-wrap gap-[var(--space-xs)]">{coverage.slice(0,4).map(([id,, ,ratio]) => <a key={id} href="#surface-trace" data-action="EVENT_BEADS_ID_CLICK" className={`badge badge-cyan ${focus}`}>{id} · {ratio}</a>)}</div></Shell>; }
function SearchInput() { return <Shell dsId="ds:webui.search.query-input"><form action="#surface-search" data-action="EVENT_SEARCH"><label className="block text-sm font-medium" htmlFor="search-explorer-query">Search query</label><input id="search-explorer-query" name="q" defaultValue="approval evidence" className={`mt-1 w-full rounded-[var(--radius)] border border-[var(--border)] bg-[var(--bg)] p-[var(--space-xs)] ${focus}`} /><button className={`mt-[var(--space-xs)] btn-primary btn-sm ${focus}`}><Icon name="search" />Search API</button></form></Shell>; }
function TypeFilters() { return <Shell dsId="ds:webui.search.type-filters"><nav aria-label="Search type filters" className="flex flex-wrap gap-[var(--space-xs)]">{["all","doc","commit","task","adr","chat","spike"].map(type => <a href={`#${type}`} data-action="EVENT_SEARCH_FILTER" data-action-id="action-search-select-filter" data-event="EVENT_SEARCH_SELECT_FILTER" className={`btn-secondary btn-sm ${focus}`} key={type}>{type}</a>)}</nav></Shell>; }
