function FileLeases() { return <Shell dsId="ds:webui.timeline.file-leases"><h3 className="font-semibold">File leases</h3>{[["apps/website/src/app/webui-pm-workspace/page.tsx","Mira Vale","11:42"],["docs/PRDs/core-gmind/PRD-04-WebUI-and-PM-Workspace.md","Owen Kaito","04:18"],["internal/api/trace_handler.go","Priya Nadir","02:06"]].map(([file,agent,time]) => <p key={file} className="mt-[var(--space-xs)] rounded-[var(--radius)] bg-[var(--bg)] p-[var(--space-xs)] text-sm"><span className="font-mono">{time}</span> {file} leased by {agent}</p>)}</Shell>; }
function SprintTimeline() { return <Shell dsId="ds:webui.timeline.sprint-day"><h3 className="font-semibold">Sprint day</h3><ol className="mt-[var(--space-sm)] space-y-[var(--space-xs)]">{["09:12 RTM coverage refreshed","10:37 approval reject path reviewed","13:48 terminal console log pinned","15:26 release train confidence vote recorded"].map(i => <li key={i} className="border-l border-[var(--border-highlight)] pl-[var(--space-sm)] text-sm">{i}</li>)}</ol></Shell>; }
function GitScenarios() { return <Shell dsId="ds:webui.git-graph.scenario-list"><div className="flex flex-wrap gap-[var(--space-xs)]">{["beads-prd-trace","release-train","hotfix-evidence"].map(x => <button key={x} data-action="EVENT_GIT_GRAPH_SELECT_SCENARIO" data-action-id="action-git-graph-select-scenario" data-event="EVENT_GIT_GRAPH_SELECT_SCENARIO" className={`btn-secondary btn-sm ${focus}`}>{x}</button>)}</div><p className={`mt-[var(--space-xs)] text-xs ${muted}`}>Scenario filters compare merge-base, branch lease, and CI artifact edges.</p></Shell>; }
function GitCanvas() { const commits = [["main","ef1d937","route loop fix"],["feature/webui-shell","293acdb","PRD route diagrams"],["fix/approval-route","f021042","surface approval redirect"],["stage2-components","4321ddb","PM Space header"]]; return <Shell dsId="ds:webui.git-graph.canvas"><ol className="grid gap-[var(--space-xs)] md:grid-cols-4">{commits.map(([b,sha,msg],i) => <li key={b} className="rounded-[var(--radius)] bg-[var(--bg)] p-[var(--space-xs)] text-sm"><a href="#surface-git-graph" data-action="EVENT_GIT_GRAPH_SELECT_COMMIT" data-action-id="action-git-graph-select-commit" data-event="EVENT_GIT_GRAPH_SELECT_COMMIT" className={`block ${focus}`}><span className="graph-node graph-node--commit">{i+1}</span><span className="ml-[var(--space-xs)] font-mono">{sha}</span><span className="block">{b}</span><span className={muted}>{msg}</span></a></li>)}</ol></Shell>; }
function CommitDetail() { return <Shell dsId="ds:webui.git-graph.commit-detail"><h3 className="font-semibold">Commit detail</h3><p className={`mt-[var(--space-xs)] text-sm ${muted}`}>ef1d937a7 resolved workspace hash routing and links to trace:approval-gate.</p><a href="#surface-trace" data-action="EVENT_GIT_GRAPH_OPEN_TRACE" data-action-id="action-git-graph-open-trace" data-event="EVENT_GIT_GRAPH_OPEN_TRACE" className={`mt-[var(--space-sm)] inline-flex btn-secondary btn-sm ${focus}`}><Icon name="trace" />Open trace</a></Shell>; }
function KnowledgePresets() { return <Shell dsId="ds:webui.knowledge-graph.preset-list"><div className="flex flex-wrap gap-[var(--space-xs)]">{["PRD to task","Task to CI","Document backlinks"].map(x => <button key={x} data-action="EVENT_KNOWLEDGE_SELECT_PRESET" data-action-id="action-knowledge-select-preset" data-event="EVENT_KNOWLEDGE_SELECT_PRESET" className={`btn-secondary btn-sm ${focus}`}>{x}</button>)}</div><ApiLabel>GET /api/graph/presets?space=pm</ApiLabel></Shell>; }
function KnowledgeCanvas() { return <Shell dsId="ds:webui.knowledge-graph.canvas"><div className="grid grid-cols-5 items-center gap-[var(--space-xs)] text-center">{graphNodes.map((node,i) => <a key={node} href="#surface-trace" data-action="EVENT_KNOWLEDGE_SELECT_NODE" data-action-id="action-knowledge-select-node" data-event="EVENT_KNOWLEDGE_SELECT_NODE" className={`graph-node ${i===0?"graph-node--prd":i===2?"graph-node--task":""} ${focus}`}>{node}</a>)}</div></Shell>; }
function KnowledgeNodeBanner() { return <Shell dsId="ds:webui.knowledge-graph.node-banner"><p className="text-sm"><strong>Selected:</strong> br-prd04-s5 approval gate. Evidence edges include bd-approval-178, PR #42, and gmind-webui-2841.</p><a href="#surface-trace" data-action="EVENT_KNOWLEDGE_OPEN_TRACE" data-action-id="action-knowledge-open-trace" data-event="EVENT_KNOWLEDGE_OPEN_TRACE" className={`mt-[var(--space-sm)] inline-flex btn-secondary btn-sm ${focus}`}><Icon name="trace" />Open trace path</a></Shell>; }
function PortfolioTable() { const rows = [["PM Workspace Shell","18.7","$84.6k","br-prd04-s8"],["Trace Explorer","14.3","$52.4k","br-prd04-s10"],["Approval Gates","21.2","$63.8k","br-prd04-s4"]]; return <Shell dsId="ds:webui.portfolio.table"><table className="data-table w-full text-sm"><thead><tr><th>Epic</th><th>WSJF</th><th>Budget</th><th>Trace</th><th>Open</th></tr></thead><tbody>{rows.map(r => <tr key={r[0]} className={row}>{r.map((c,i)=><td key={c} className={i===3?"font-mono":""}>{c}</td>)}<td><a href="#surface-tasks" data-action="EVENT_PORTFOLIO_OPEN_EPIC_TASKS" data-action-id="action-portfolio-open-epic-tasks" data-event="EVENT_PORTFOLIO_OPEN_EPIC_TASKS" className={`badge badge-cyan ${focus}`}>Tasks</a></td></tr>)}</tbody></table></Shell>; }
function PortfolioRoadmap() { return <Shell dsId="ds:webui.portfolio.roadmap"><h3 className="font-semibold">Roadmap</h3>{["PI-4 discovery","PI-5 shell hardening","PI-6 approval automation"].map((x,i)=><p key={x} className="mt-[var(--space-xs)] rounded-[var(--radius)] bg-[var(--bg)] p-[var(--space-xs)] text-sm">{i+1}. {x}</p>)}<a href="#surface-trace" data-action="EVENT_PORTFOLIO_OPEN_BUDGET_TRACE" data-action-id="action-portfolio-open-budget-trace" data-event="EVENT_PORTFOLIO_OPEN_BUDGET_TRACE" className={`mt-[var(--space-sm)] inline-flex btn-secondary btn-sm ${focus}`}>Open budget trace</a></Shell>; }
function StrategicSandbox() { return <Shell dsId="ds:webui.pi-planning.strategic-sandbox"><h3 className="font-semibold">Strategic sandbox</h3><button data-action="EVENT_PI_DRAG_FEATURE" className={`mt-[var(--space-xs)] btn-secondary btn-sm ${focus}`}>Move approval evidence feature to stretch lane</button></Shell>; }
function CapacityPlan() { return <Shell dsId="ds:webui.pi-planning.capacity-plan"><dl className="grid grid-cols-3 gap-[var(--space-xs)] text-sm"><div><dt className={muted}>Team capacity</dt><dd className="font-mono">183.5 pts</dd></div><div><dt className={muted}>Planned</dt><dd className="font-mono">156.8 pts</dd></div><div><dt className={muted}>Risk reserve</dt><dd className="font-mono">26.7 pts</dd></div></dl></Shell>; }
function ValueScoring() { return <Shell dsId="ds:webui.pi-planning.value-scoring"><label className="text-sm font-medium">Business value<input readOnly value="17.6" className={`mt-1 w-full rounded-[var(--radius)] border border-[var(--border)] bg-[var(--bg)] p-[var(--space-xs)] ${focus}`} /></label></Shell>; }
function ConfidenceVote() { return <Shell dsId="ds:webui.pi-planning.confidence-vote"><div className="flex gap-[var(--space-xs)]">{[3,4,5].map(v=><button key={v} data-action="EVENT_PI_CONFIDENCE" data-action-id="action-pi-submit-confidence-vote" data-event="EVENT_PI_SUBMIT_CONFIDENCE_VOTE" className={`btn-secondary btn-sm ${focus}`}>{v}</button>)}</div></Shell>; }
function RoamBoard() { return <Shell dsId="ds:webui.pi-planning.roam-board"><p className="text-sm">Dependencies: API trace adapter before approval decision audit; document backlinks before storyboard review.</p></Shell>; }
function StoryboardFilter() { return <Shell dsId="ds:webui.storyboards.filter"><label className="text-sm font-medium">Journey filter<select className={`mt-1 w-full rounded-[var(--radius)] border border-[var(--border)] bg-[var(--bg)] p-[var(--space-xs)] ${focus}`} defaultValue="approval"><option value="approval">approval evidence</option><option value="trace">trace drilldown</option></select></label></Shell>; }
function StoryboardFlow() { return <Shell dsId="ds:webui.storyboards.flow"><ol className="grid gap-[var(--space-xs)] md:grid-cols-4 text-sm">{["Open approval", "Review evidence", "Submit decision", "Audit trace"].map(x=><li key={x} className="rounded-[var(--radius)] bg-[var(--bg)] p-[var(--space-xs)]">{x}</li>)}</ol></Shell>; }
function GuidancePanel() { return <Shell dsId="ds:webui.storyboards.guidance-panel"><p className="text-sm">Storyboard confirms PMO can reach approval, trace, docs, terminal, and timeline surfaces without shell navigation loss.</p></Shell>; }
function StoryboardSummary() { return <Shell dsId="ds:webui.storyboard-detail.summary"><h3 className="font-semibold">Approval decision journey</h3><p className={`mt-[var(--space-xs)] text-sm ${muted}`}>Role: RTE approver. Goal: verify evidence and submit auditable decision.</p></Shell>; }
function StoryboardTimeline() { return <Shell dsId="ds:webui.storyboard-detail.timeline"><ol className="space-y-[var(--space-xs)] text-sm">{["Select bd-approval-178", "Open trace context", "Request missing CI note", "Submit approval"].map(x=><li key={x} className="border-l border-[var(--border-highlight)] pl-[var(--space-sm)]">{x}</li>)}</ol></Shell>; }
function RelatedUsecases() { return <Shell dsId="ds:webui.storyboard-detail.related-usecases"><div className="flex flex-wrap gap-[var(--space-xs)]">{["RTM drilldown","Task detail edit","Git graph audit"].map(x=><a key={x} href="#surface-storyboards" data-action="EVENT_STORYBOARD_OPEN" data-action-id="action-storyboards-open-detail" data-event="EVENT_STORYBOARDS_OPEN_DETAIL" className={`badge badge-cyan ${focus}`}>{x}</a>)}</div></Shell>; }
function CatalogNav() { return <Shell dsId="ds:webui.components.section-nav"><nav className="flex flex-wrap gap-[var(--space-xs)]" aria-label="Component sections">{["Shell","Dashboard","Graphs","Approval","Planning"].map(x=><a key={x} href={`#${x.toLowerCase()}`} data-action="EVENT_COMPONENTS_SCROLL_SECTION" data-action-id="action-components-scroll-section" data-event="EVENT_COMPONENTS_SCROLL_SECTION" className={`btn-secondary btn-sm ${focus}`}>{x}</a>)}</nav></Shell>; }
function CatalogExamples() { const [expanded, setExpanded] = useState(false); return <Shell dsId="ds:webui.components.examples"><div className="flex items-center justify-between gap-[var(--space-sm)]"><h3 className="font-semibold">Examples</h3><button type="button" data-action="EVENT_COMPONENTS_TOGGLE_EXAMPLE" data-action-id="action-components-toggle-example" data-event="EVENT_COMPONENTS_TOGGLE_EXAMPLE" aria-expanded={expanded} onClick={() => setExpanded((value) => !value)} className={`btn-secondary btn-sm ${focus}`}>{expanded ? "Hide anatomy" : "Show anatomy"}</button></div><p className="mt-[var(--space-xs)] text-sm">Buttons, badges, data tables, graph nodes, state panels, and shell navigation patterns used in this workspace.</p>{expanded ? <dl className="mt-[var(--space-sm)] grid gap-[var(--space-xs)] text-sm"><div><dt className="font-mono text-xs text-[var(--text-dim)]">Attributes</dt><dd>Every interactive example keeps data-action-id and data-event paired with contract actions.</dd></div><div><dt className="font-mono text-xs text-[var(--text-dim)]">Source</dt><dd>ui-contract action catalog, Mermaid events, and storyboard replay actions.</dd></div></dl> : null}</Shell>; }
function TokenReference() { return <Shell dsId="ds:webui.components.tokens"><div className="grid gap-[var(--space-xs)] sm:grid-cols-3 text-sm">{["--surface","--border","--accent-cyan"].map(x=><code key={x} className="rounded-[var(--radius)] bg-[var(--bg)] p-[var(--space-xs)]">{x}</code>)}</div><p className={`mt-[var(--space-xs)] text-xs ${muted}`}>Catalog examples inherit DS tokens only; no hardcoded color samples are rendered.</p></Shell>; }
function Fallback({ dsId }: { dsId: string }) { return <Shell dsId={dsId}><p className="font-mono text-xs text-[var(--text-dim)]">{dsId}</p><p className="mt-[var(--space-xs)] text-sm">Component mapping retained for contract traceability.</p></Shell>; }
